{"code": "import pandas as pd, numpy as np
import statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
for e in ['potassium_ppm','irrigation_mm','shade_pct']:
    print("===",e)
    for f in df['farm'].unique():
        sub = df[df['farm']==f]
        m = smf.ols(f'yield_kg ~ {e}', data=sub).fit()
        print(f"  {f:6s} coef={m.params[e]:8.4f} p={m.pvalues[e]:.3g} n={len(sub)}")
"}
